#[path = "src/idna.rs"]
mod idna;
#[path = "src/validate.rs"]
mod validate;
#[path = "src/text.rs"]
mod text;

use std::io::Write;
use std::os::unix::ffi::OsStrExt;

fn as_byte(b: bool) -> &'static [u8] {
    if b {
        b"1"
    } else {
        b"0"
    }
}

fn main() {
    let args: Vec<Vec<u8>> = std::env::args_os()
        .skip(1)
        .map(|a| a.as_bytes().to_vec())
        .collect();
    let inputs: Vec<Vec<u8>> = if args.is_empty() {
        vec![
            b"one".to_vec(),
            b"two.three".to_vec(),
            b"four.five.six".to_vec(),
        ]
    } else {
        args
    };

    let stdout = std::io::stdout();
    let mut out = stdout.lock();

    for input in &inputs {
        let fields: Vec<Vec<u8>> = vec![
            idna::to_ascii(input),
            idna::to_unicode(input),
            punycode::punycode_encode(input),
            punycode::punycode_decode(input),
            as_byte(validate::is_valid_domain(input)).to_vec(),
            as_byte(validate::is_valid_label(input)).to_vec(),
            as_byte(validate::is_ascii_domain(input)).to_vec(),
            as_byte(validate::is_idn_domain(input)).to_vec(),
            text::to_lower(input),
            text::normalize(input),
            validate::count_labels(input).to_string().into_bytes(),
        ];
        let mut line = Vec::new();
        for (i, field) in fields.iter().enumerate() {
            if i > 0 {
                line.push(b' ');
            }
            line.extend_from_slice(field);
        }
        line.push(b'\n');
        out.write_all(&line).unwrap();
    }
}

